def solve(grid):
    # Find the separator row (all 4s)
    sep_idx = None
    for i, row in enumerate(grid):
        if all(x == 4 for x in row):
            sep_idx = i
            break

    # Split into top and bottom grids
    top = grid[:sep_idx]
    bottom = grid[sep_idx + 1:]

    rows = len(top)
    cols = len(top[0]) if rows > 0 else 0

    # Create result grid
    result = [[0 for _ in range(cols)] for _ in range(rows)]

    # Place 3 where both grids have 0
    for i in range(rows):
        for j in range(cols):
            if top[i][j] == 0 and bottom[i][j] == 0:
                result[i][j] = 3

    return result
